answers.workaround:
Based on https://github.com/godotengine/godot/issues/57898#issuecomment-1872992257 we are using this gross function in our project at the moment:

```
func _center_editor_view_to_point(pos: Vector2, zoom: float = 100.0) -> void:
	if not Engine.is_editor_hint():
		return

	# this whole function is gross because:
	# 1. we're avoiding referencing EditorInterface from release builds as it leads to compile errors.
	# 2. we're calling internal / unexposed functions to EditorZoomWidget.

	@warning_ignore("untyped_declaration")
	var editor_interface = Engine.get_singleton(&"EditorInterface")

	@warning_ignore("unsafe_cast")
	var editor_control: Control = editor_interface.call(&"get_base_control") as Control
	var editor_viewport: Control = editor_control.find_child("@CanvasItemEditorViewport*", true, false)

	@warning_ignore("untyped_declaration")
	var zoomer = editor_viewport.find_child("@EditorZoomWidget*", true, false)

	@warning_ignore("unsafe_method_access")
	zoomer.set_zoom(zoom)

	@warning_ignore("unsafe_property_access")
	@warning_ignore("unsafe_method_access")
	zoomer.zoom_changed.emit(zoom)

	# add offset to center
	pos -= (editor_viewport.size / zoom) / 2.0

	var hscroll: HScrollBar = editor_viewport.find_child("@HScrollBar*", true, false)
	hscroll.value = pos.x
	var vscroll: VScrollBar = editor_viewport.find_child("@VScrollBar*", true, false)
	vscroll.value = pos.y
```
